function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

const dummy = new THREE.Object3D();
const tmpColor = new THREE.Color();

function instance(geom, mat, count, parent) {
  const m = new THREE.InstancedMesh(geom, mat, count);
  m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  m.frustumCulled = true;
  parent.add(m);
  return m;
}

function placeInstances(mesh, list, colorize = false) {
  list.forEach((it, i) => {
    dummy.position.set(it.x, it.y, it.z);
    dummy.rotation.set(it.rx || 0, it.ry || 0, it.rz || 0);
    dummy.scale.set(it.sx ?? 1, it.sy ?? 1, it.sz ?? 1);
    dummy.updateMatrix();
    mesh.setMatrixAt(i, dummy.matrix);
    if (colorize && it.color) mesh.setColorAt(i, tmpColor.set(it.color));
  });
  mesh.instanceMatrix.needsUpdate = true;
  if (colorize && mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
}

export function createEnvironment(arena, courseLength, quality = 'high') {
  const group = new THREE.Group();
  const anim = [];
  const rand = rng((arena.id || 'classic').split('').reduce((a, c) => a + c.charCodeAt(0), 77) * 97);
  const low = quality === 'low';

  // ---------- sky dome ----------
  const skyUniforms = {
    uTop: { value: new THREE.Color(arena.skyTop) },
    uHorizon: { value: new THREE.Color(arena.skyHorizon) },
    uSun: { value: new THREE.Color(arena.sun) },
    uSunDir: { value: new THREE.Vector3(...arena.sunDir).normalize() },
    uTime: { value: 0 },
    uNight: { value: arena.id === 'night' ? 1 : 0 }
  };
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: skyUniforms,
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: `
      uniform vec3 uTop; uniform vec3 uHorizon; uniform vec3 uSun; uniform vec3 uSunDir;
      uniform float uTime; uniform float uNight;
      varying vec3 vDir;
      float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
      void main(){
        vec3 d = normalize(vDir);
        float h = clamp(d.y, 0.0, 1.0);
        vec3 col = mix(uHorizon, uTop, pow(h, 0.55));
        float sd = max(dot(d, uSunDir), 0.0);
        col += uSun * pow(sd, 300.0) * 2.4;
        col += uSun * pow(sd, 7.0) * 0.12;
        // stylised cloud bands
        float cl = sin(d.x * 7.0 + uTime * 0.015) * sin(d.z * 5.0 - uTime * 0.01)
                 + 0.5 * sin(d.x * 13.0 - d.z * 9.0 + uTime * 0.02);
        cl = smoothstep(0.55, 1.15, cl) * smoothstep(0.03, 0.3, h) * (1.0 - uNight);
        col = mix(col, uHorizon * 1.18 + vec3(0.08), cl * 0.42);
        // stars
        if (uNight > 0.5) {
          vec2 sp = vec2(atan(d.z, d.x) * 3.0, d.y * 8.0);
          vec2 cell = floor(sp * 18.0);
          float star = step(0.9965, hash(cell)) * smoothstep(0.05, 0.35, h);
          col += vec3(star) * (0.6 + 0.4 * sin(uTime * 2.0 + hash(cell) * 6.28));
        }
        gl_FragColor = vec4(col, 1.0);
      }
    `
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(620, 24, 16), skyMat);
  sky.frustumCulled = false;
  group.add(sky);

  // ---------- animated water ----------
  const waterUniforms = {
    uTime: { value: 0 },
    uShallow: { value: new THREE.Color(arena.waterShallow) },
    uDeep: { value: new THREE.Color(arena.waterDeep) },
    uFog: { value: new THREE.Color(arena.fog) },
    uSun: { value: new THREE.Color(arena.sun) }
  };
  const waterGeo = new THREE.PlaneGeometry(1100, 1100, low ? 42 : 90, low ? 42 : 90);
  waterGeo.rotateX(-Math.PI / 2);
  const waterMat = new THREE.ShaderMaterial({
    uniforms: waterUniforms, fog: false,
    vertexShader: `
      uniform float uTime;
      varying vec3 vWorld; varying float vWave;
      void main(){
        vec3 p = position;
        float w = sin(p.x * 0.09 + uTime * 1.15) * 0.18
                + sin(p.z * 0.13 - uTime * 0.95) * 0.16
                + sin((p.x + p.z) * 0.055 + uTime * 0.6) * 0.24;
        p.y += w;
        vWave = w;
        vec4 wp = modelMatrix * vec4(p, 1.0);
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      uniform float uTime; uniform vec3 uShallow; uniform vec3 uDeep; uniform vec3 uFog; uniform vec3 uSun;
      varying vec3 vWorld; varying float vWave;
      void main(){
        float dist = length(vWorld.xz - cameraPosition.xz);
        vec3 col = mix(uShallow, uDeep, smoothstep(0.0, 1.0, clamp((vWave + 0.55) / 1.1, 0.0, 1.0)));
        float ripple = sin(vWorld.x * 0.55 + uTime * 2.1) * sin(vWorld.z * 0.42 - uTime * 1.7);
        col += ripple * 0.035;
        float spark = pow(max(0.0, sin(vWorld.x * 0.9 + uTime * 2.5) * sin(vWorld.z * 1.1 - uTime * 2.0)), 18.0);
        col += uSun * spark * 0.5;
        col = mix(col, uFog, smoothstep(70.0, 330.0, dist) * 0.82);
        gl_FragColor = vec4(col, 1.0);
      }
    `
  });
  const water = new THREE.Mesh(waterGeo, waterMat);
  water.position.y = -2.25;
  water.frustumCulled = false;
  group.add(water);

  // ---------- distant islands / banks ----------
  const islandMat = toonMat(arena.ground);
  const islandGeo = new THREE.SphereGeometry(1, 12, 8);
  for (let i = 0; i < (low ? 7 : 13); i++) {
    const side = i % 2 ? 1 : -1;
    const z = 30 - (i / (low ? 7 : 13)) * (courseLength + 220) + rand() * 30;
    const s = 12 + rand() * 28;
    const isl = new THREE.Mesh(islandGeo, islandMat);
    isl.position.set(side * (46 + rand() * 55), -7 - rand() * 5, z);
    isl.scale.set(s, 5 + rand() * 7, s * 0.8);
    group.add(isl);
    if (!low) {
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(1, 0), toonMat(arena.platformSide));
      rock.position.set(side * (40 + rand() * 20), -1.4, z + rand() * 20);
      rock.scale.set(1.4 + rand() * 2.4, 1 + rand() * 2.6, 1.4 + rand() * 2.4);
      rock.rotation.y = rand() * 6;
      group.add(rock);
    }
  }

  // ---------- scenery by theme ----------
  const propGroup = new THREE.Group();
  group.add(propGroup);

  const addPalms = (count) => {
    const trunkGeo = new THREE.CylinderGeometry(0.28, 0.42, 7, 6);
    const trunkMat = toonMat('#9b6a3d');
    const frondGeo = new THREE.ConeGeometry(1.9, 0.5, 5);
    const frondMat = toonMat('#2fa860');
    const trunks = instance(trunkGeo, trunkMat, count, propGroup);
    const leaves = instance(frondGeo, frondMat, count * 3, propGroup);
    const trunksL = [], leavesL = [];
    for (let i = 0; i < count; i++) {
      const side = rand() > 0.5 ? 1 : -1;
      const x = side * (15 + rand() * 26);
      const z = 12 - rand() * (courseLength + 60);
      const h = 6 + rand() * 6;
      trunksL.push({ x, y: -1.4 + h * 0.4, z, sy: h / 7, ry: rand() * 6 });
      for (let k = 0; k < 3; k++) {
        leavesL.push({
          x, y: -1.4 + h * 0.85, z,
          rz: 0.5 + k * 0.22, ry: rand() * 6, sx: 1, sy: 1, sz: 1
        });
      }
    }
    placeInstances(trunks, trunksL);
    placeInstances(leaves, leavesL);
  };

  const addStands = (count) => {
    const standMat = toonMat(arena.platformSide);
    const seatMat = toonMat(arena.platform);
    const crowdGeo = new THREE.BoxGeometry(0.42, 0.6, 0.4);
    const crowdMat = toonMat('#ffffff');
    const crowd = instance(crowdGeo, crowdMat, count * 90, propGroup);
    const seats = instance(new THREE.BoxGeometry(1, 1, 1), seatMat, count * 12, propGroup);
    const standL = [], seatsL = [], crowdL = [];
    for (let i = 0; i < count; i++) {
      const side = i % 2 ? 1 : -1;
      const z = -i * 46 - 8;
      for (let t = 0; t < 12; t++) {
        const row = Math.floor(t / 3);
        seatsL.push({
          x: side * (17 + row * 2.0), y: -0.2 + row * 1.1, z: z - (t % 3) * 3,
          sx: 4.5, sy: 1, sz: 2.2
        });
        for (let c = 0; c < 6; c++) {
          crowdL.push({
            x: side * (17 + row * 2.0 - 1.2), y: 0.65 + row * 1.1, z: z - (t % 3) * 3 - 0.7 + c * 0.28,
            color: arena.crowd[(i + t + c) % arena.crowd.length],
            ry: (rand() - 0.5) * 0.7, sy: 0.8 + rand() * 0.5
          });
        }
      }
    }
    placeInstances(seats, seatsL);
    placeInstances(crowd, crowdL, true);
  };

  const addPines = (count) => {
    const trunk = instance(new THREE.CylinderGeometry(0.24, 0.34, 3, 5), toonMat('#6c4a33'), count, propGroup);
    const leafGeo = new THREE.ConeGeometry(2.2, 4.2, 7);
    const leaf = instance(leafGeo, toonMat('#2c7a5b'), count * 3, propGroup);
    const trunkL = [], leafL = [];
    for (let i = 0; i < count; i++) {
      const side = rand() > 0.5 ? 1 : -1;
      const x = side * (16 + rand() * 24);
      const z = 18 - rand() * (courseLength + 80);
      const s = 0.7 + rand() * 0.9;
      trunkL.push({ x, y: 1.2 * s - 1.5, z, sy: s, sx: s, sz: s });
      for (let k = 0; k < 3; k++) {
        leafL.push({ x, y: -0.5 + (2.4 + k * 1.55) * s, z, sx: s * (1 - k * 0.2), sy: s * (1 - k * 0.15), sz: s * (1 - k * 0.2) });
      }
    }
    placeInstances(trunk, trunkL);
    placeInstances(leaf, leafL);
  };

  const addCacti = (count) => {
    const body = instance(new THREE.CylinderGeometry(0.55, 0.62, 4.2, 7), toonMat('#3e8f57'), count * 3, propGroup);
    const list = [];
    for (let i = 0; i < count; i++) {
      const side = rand() > 0.5 ? 1 : -1;
      const x = side * (15 + rand() * 28);
      const z = 15 - rand() * (courseLength + 60);
      const s = 0.7 + rand() * 0.9;
      list.push({ x, y: 0.6 * s - 1.3, z, sy: s, sx: s, sz: s });
      list.push({ x: x + 0.7 * s, y: 1.2 * s - 1.3, z, rz: -0.9, sx: s * 0.6, sy: s * 0.55, sz: s * 0.6 });
      list.push({ x: x - 0.7 * s, y: 0.8 * s - 1.3, z, rz: 0.9, sx: s * 0.55, sy: s * 0.45, sz: s * 0.55 });
    }
    placeInstances(body, list);
    // rock towers
    const rocks = instance(new THREE.CylinderGeometry(1.6, 2.6, 1, 6), toonMat('#c98a51'), low ? 5 : 11, propGroup);
    const rocksL = [];
    for (let i = 0; i < (low ? 5 : 11); i++) {
      const side = i % 2 ? 1 : -1;
      rocksL.push({ x: side * (26 + rand() * 25), y: 3 + rand() * 5, z: 10 - rand() * (courseLength + 100), sy: 7 + rand() * 9, sx: 1 + rand() * 0.8, sz: 0.8 + rand() * 0.8, ry: rand() * 6 });
    }
    placeInstances(rocks, rocksL);
  };

  const addContainers = (count) => {
    const contGeo = new THREE.BoxGeometry(1, 1, 1);
    const cont = instance(contGeo, toonMat('#ffffff'), count, propGroup, true);
    const list = [];
    const colors = ['#c94a2b', '#2e6f8f', '#d6a93a', '#4a7c59', '#5b5f66', '#a34a4a'];
    for (let i = 0; i < count; i++) {
      const side = rand() > 0.5 ? 1 : -1;
      const stack = 1 + Math.floor(rand() * 3);
      for (let k = 0; k < stack; k++) {
        list.push({
          x: side * (19 + rand() * 26), y: -1 + k * 3.1, z: 15 - rand() * (courseLength + 40),
          sx: 8 + rand() * 3, sy: 3, sz: 3.2, ry: (rand() - 0.5) * 0.3,
          color: colors[(i + k) % colors.length]
        });
      }
    }
    placeInstances(cont, list, true);
    // smokestacks
    const stacks = instance(new THREE.CylinderGeometry(2, 2.8, 1, 10), toonMat('#4a545a'), 8, propGroup);
    const stacksL = [];
    for (let i = 0; i < 8; i++) {
      stacksL.push({ x: (i % 2 ? 1 : -1) * (40 + rand() * 18), y: 10, z: -i * 55 - 20, sy: 24 + rand() * 16, sx: 1, sz: 1 });
    }
    placeInstances(stacks, stacksL);
    // smoke puffs
    const puffMat = toonMat('#d8dde0', { transparent: true, opacity: 0.55 });
    for (let i = 0; i < 5; i++) {
      const p = new THREE.Mesh(new THREE.SphereGeometry(1, 8, 6), puffMat);
      p.position.set((i % 2 ? 1 : -1) * (44 + rand() * 12), 20 + rand() * 8, -i * 55 - 20);
      p.scale.setScalar(3 + rand() * 3);
      propGroup.add(p);
      anim.push({ type: 'rise', mesh: p, base: p.position.y, speed: 0.4 + rand() * 0.3, t: rand() * 6 });
    }
  };

  const addNight = (count) => {
    const towers = instance(new THREE.CylinderGeometry(0.35, 0.55, 1, 6), toonMat('#2b3570'), count, propGroup);
    const list = [];
    for (let i = 0; i < count; i++) {
      const side = i % 2 ? 1 : -1;
      list.push({ x: side * (20 + rand() * 20), y: 8, z: 10 - i * (courseLength / count), sy: 18 + rand() * 8 });
    }
    placeInstances(towers, list);
    const glowMat = toonMat(arena.accent2, { emissive: arena.accent2, emissiveIntensity: 1 });
    const bulbs = instance(new THREE.SphereGeometry(0.7, 7, 5), glowMat, count * 2, propGroup);
    const bulbsL = [];
    list.forEach(l => {
      bulbsL.push({ x: l.x, y: l.y + l.sy / 2 + 0.8, z: l.z });
      bulbsL.push({ x: l.x, y: l.y, z: l.z });
    });
    placeInstances(bulbs, bulbsL);
    // neon arches across the course
    for (let i = 0; i < 4; i++) {
      const mat = toonMat(i % 2 ? arena.accent : arena.accent2, { emissive: i % 2 ? arena.accent : arena.accent2, emissiveIntensity: 0.8 });
      const arch = new THREE.Mesh(new THREE.TorusGeometry(11, 0.28, 6, 24, Math.PI), mat);
      arch.position.set(0, 3.4, -25 - i * 62);
      arch.rotation.z = Math.PI;
      propGroup.add(arch);
    }
    // spotlights
    for (let i = 0; i < 3; i++) {
      const beam = new THREE.Mesh(
        new THREE.ConeGeometry(5, 55, 12, 1, true),
        new THREE.MeshBasicMaterial({ color: arena.accent2, transparent: true, opacity: 0.05, depthWrite: false, side: THREE.DoubleSide })
      );
      beam.position.set((i - 1) * 38, 24, -60 - i * 55);
      beam.rotation.z = (i - 1) * 0.4;
      propGroup.add(beam);
      anim.push({ type: 'sway', mesh: beam, base: beam.rotation.z, speed: 0.3 + i * 0.1 });
    }
  };

  if (arena.props === 'stadium') {
    addStands(low ? 4 : 7);
    // inflatable start arch and buoys
    const buoyMat = toonMat(arena.accent);
    for (let i = 0; i < Math.floor(courseLength / 26); i++) {
      const side = i % 2 ? 1 : -1;
      const b = new THREE.Mesh(new THREE.TorusGeometry(1.5, 0.55, 8, 16), buoyMat);
      b.position.set(side * (12.5 + rand() * 3), -0.8, -i * 26 - 8);
      b.rotation.x = Math.PI / 2;
      group.add(b);
      anim.push({ type: 'bob', mesh: b, base: -0.8, phase: rand() * 6 });
    }
    // distant jumbotron
    const screen = new THREE.Mesh(new THREE.BoxGeometry(20, 11, 2), toonMat('#1b2c47', { emissive: '#1e6f8a', emissiveIntensity: 0.4 }));
    screen.position.set(0, 15, -courseLength - 30);
    propGroup.add(screen);
    const frame = new THREE.Mesh(new THREE.BoxGeometry(22, 13, 1), toonMat('#c9d6e2'));
    frame.position.set(0, 15, -courseLength - 32);
    propGroup.add(frame);
  } else if (arena.props === 'tropical') {
    addPalms(low ? 10 : 22);
    addStands(low ? 2 : 4);
    const hutMat = toonMat('#9b6a3d');
    const roofMat = toonMat('#e8a33e');
    for (let i = 0; i < 4; i++) {
      const side = i % 2 ? 1 : -1;
      const x = side * (20 + rand() * 8), z = 4 - i * 48;
      const hut = new THREE.Mesh(new THREE.BoxGeometry(5, 3, 5), hutMat);
      hut.position.set(x, 0.5, z);
      propGroup.add(hut);
      const roof = new THREE.Mesh(new THREE.ConeGeometry(4.6, 2.6, 4), roofMat);
      roof.position.set(x, 3.1, z); roof.rotation.y = Math.PI / 4;
      propGroup.add(roof);
    }
  } else if (arena.props === 'winter') {
    addPines(low ? 12 : 26);
    addStands(low ? 3 : 5);
    // snow banks
    const snow = instance(new THREE.SphereGeometry(1, 9, 7), toonMat('#f4fbff'), low ? 10 : 22, propGroup);
    const snowL = [];
    for (let i = 0; i < (low ? 10 : 22); i++) {
      const side = i % 2 ? 1 : -1;
      snowL.push({ x: side * (14 + rand() * 30), y: -2.6 + rand() * 0.8, z: 20 - rand() * (courseLength + 80), sx: 3 + rand() * 6, sy: 1.4 + rand() * 2, sz: 3 + rand() * 6 });
    }
    placeInstances(snow, snowL);
    // snowfall
    if (!low) {
      const count = 500;
      const pos = new Float32Array(count * 3);
      for (let i = 0; i < count; i++) {
        pos[i * 3] = (rand() - 0.5) * 90;
        pos[i * 3 + 1] = rand() * 32;
        pos[i * 3 + 2] = 20 - rand() * (courseLength + 40);
      }
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      const pts = new THREE.Points(g, new THREE.PointsMaterial({ color: '#ffffff', size: 0.38, transparent: true, opacity: 0.85, depthWrite: false }));
      group.add(pts);
      anim.push({ type: 'snow', points: pts, count });
    }
  } else if (arena.props === 'desert') {
    addCacti(low ? 8 : 16);
    addStands(low ? 2 : 4);
    const dunes = instance(new THREE.SphereGeometry(1, 10, 6), toonMat('#e7b06b'), low ? 6 : 12, propGroup);
    const dunesL = [];
    for (let i = 0; i < (low ? 6 : 12); i++) {
      const side = i % 2 ? 1 : -1;
      dunesL.push({ x: side * (38 + rand() * 20), y: -4, z: 20 - i * (courseLength / 10), sx: 20 + rand() * 16, sy: 5 + rand() * 6, sz: 16 + rand() * 14 });
    }
    placeInstances(dunes, dunesL);
  } else if (arena.props === 'night') {
    addNight(low ? 6 : 12);
    addStands(low ? 3 : 6);
    addPalms(low ? 4 : 8);
  } else if (arena.props === 'industrial') {
    addContainers(low ? 10 : 20);
    // cranes
    const craneMat = toonMat('#e2a32e');
    for (let i = 0; i < 2; i++) {
      const crane = new THREE.Group();
      const mast = new THREE.Mesh(new THREE.BoxGeometry(1.2, 26, 1.2), craneMat);
      mast.position.y = 12;
      const jib = new THREE.Mesh(new THREE.BoxGeometry(28, 1, 1.2), craneMat);
      jib.position.set(10, 25, 0);
      crane.add(mast, jib);
      crane.position.set(i ? 32 : -32, -2, -40 - i * 80);
      propGroup.add(crane);
    }
    const waterTower = new THREE.Mesh(new THREE.CylinderGeometry(3, 3, 7, 10), toonMat('#8a9499'));
    waterTower.position.set(-30, 8, -110);
    propGroup.add(waterTower);
  }

  // common course-side markers every ~22 units
  const markerMat = toonMat(arena.accent);
  const markerDark = toonMat(arena.platformSide);
  const markerGeo = new THREE.CylinderGeometry(0.35, 0.35, 3.4, 6);
  const markers = instance(markerGeo, markerDark, 2 * Math.ceil(courseLength / 22), group);
  const flags = instance(new THREE.ConeGeometry(1.1, 2.2, 3), markerMat, 2 * Math.ceil(courseLength / 22), group);
  const markersL = [], flagsL = [];
  for (let z = 4; z > -courseLength; z -= 22) {
    [-1, 1].forEach(side => {
      markersL.push({ x: side * 12.4, y: 0.2, z });
      flagsL.push({ x: side * 12.4, y: 2.4, z, ry: Math.PI / 4 });
    });
  }
  placeInstances(markers, markersL);
  placeInstances(flags, flagsL);

  // ambient background character shapes (small floating inflatables)
  for (let i = 0; i < 4; i++) {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(2.4, 0.8, 8, 18), toonMat(arena.crowd[i % arena.crowd.length]));
    ring.position.set((i % 2 ? 1 : -1) * (22 + i * 4), 3 + i, -20 - i * 37);
    ring.rotation.set(Math.PI / 2.4, i, 0);
    group.add(ring);
    anim.push({ type: 'bob', mesh: ring, base: ring.position.y, phase: i * 1.7 });
  }

  // ---------- lights ----------
  const hemi = new THREE.HemisphereLight(arena.hemi, arena.ground, arena.id === 'night' ? 0.9 : 1.15);
  group.add(hemi);
  const sun = new THREE.DirectionalLight(arena.sun, arena.id === 'night' ? 1.1 : 1.9);
  sun.position.set(...arena.sunDir).multiplyScalar(60);
  group.add(sun);
  const fill = new THREE.DirectionalLight(arena.accent2, 0.3);
  fill.position.set(-40, 20, 20);
  group.add(fill);

  function update(dt, t) {
    skyUniforms.uTime.value = t;
    waterUniforms.uTime.value = t;
    for (const a of anim) {
      if (a.type === 'bob') {
        a.mesh.position.y = a.base + Math.sin(t * 1.4 + (a.phase || 0)) * 0.20;
        a.mesh.rotation.z += dt * 0.12;
      } else if (a.type === 'snow') {
        const arr = a.points.geometry.attributes.position.array;
        for (let i = 0; i < a.count; i++) {
          arr[i * 3 + 1] -= dt * (2.2 + (i % 5) * 0.4);
          arr[i * 3] += Math.sin(t * 0.8 + i) * dt * 0.5;
          if (arr[i * 3 + 1] < -3) arr[i * 3 + 1] = 30;
        }
        a.points.geometry.attributes.position.needsUpdate = true;
      } else if (a.type === 'rise') {
        a.mesh.position.y += dt * a.speed;
        a.mesh.scale.x += dt * 0.15;
        a.mesh.scale.z = a.mesh.scale.x;
        if (a.mesh.position.y > 38) a.mesh.position.y = a.base;
      } else if (a.type === 'sway') {
        a.mesh.rotation.z = a.base + Math.sin(t * a.speed) * 0.12;
      }
    }
  }

  return { group, update, water, sky, lights: { hemi, sun } };
}

import * as THREE from 'three';
import { toonMat } from './characterRig.js';

// ---------------------------------------------------------------------------
// Shared geometry / helpers
// ---------------------------------------------------------------------------
const G = {
  box: new THREE.BoxGeometry(1, 1, 1),
  sphere: new THREE.SphereGeometry(1, 18, 14),
  cyl: new THREE.CylinderGeometry(1, 1, 1, 14),
  cylAxisX: (() => { const g = new THREE.CylinderGeometry(1, 1, 1, 14); g.rotateZ(Math.PI / 2); return g; })(),
  torus: new THREE.TorusGeometry(1, 0.14, 8, 20)
};

function mesh(parent, geom, mat, pos, scale, rot) {
  const m = new THREE.Mesh(geom, mat);
  if (pos) m.position.set(...pos);
  if (scale) m.scale.set(...scale);
  if (rot) m.rotation.set(...rot);
  parent.add(m);
  return m;
}

const stripeCanvases = new Map();
function stripeTexture(a, b, repeat = 4) {
  const key = a + b + repeat;
  if (stripeCanvases.has(key)) return stripeCanvases.get(key);
  const c = document.createElement('canvas');
  c.width = 128; c.height = 32;
  const ctx = c.getContext('2d');
  ctx.fillStyle = a; ctx.fillRect(0, 0, 128, 32);
  ctx.fillStyle = b;
  for (let i = -4; i < 12; i++) {
    ctx.beginPath();
    ctx.moveTo(i * 16, 0); ctx.lineTo(i * 16 + 9, 0); ctx.lineTo(i * 16 - 7, 32); ctx.lineTo(i * 16 - 16, 32);
    ctx.fill();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeat, 1);
  tex.colorSpace = THREE.SRGBColorSpace;
  stripeCanvases.set(key, tex);
  return tex;
}

function hazardMat(arena) {
  return new THREE.MeshToonMaterial({ map: stripeTexture(arena.accent, '#222831', 5) });
}

function glow(parent, color, pos, radius = 0.18) {
  return mesh(parent, G.sphere, toonMat(color, { emissive: color, emissiveIntensity: 1.4 }), pos, [radius, radius, radius]);
}

export const WATER_Y = -2.25;

// ---------------------------------------------------------------------------
// BIG RED BALL
// ---------------------------------------------------------------------------
function bigBall(opt, arena) {
  const group = new THREE.Group();
  group.position.set(opt.x, opt.top, opt.z);
  const r = opt.radius || 1.85;
  const spinGroup = new THREE.Group();
  spinGroup.position.y = r;
  group.add(spinGroup);

  const ballMat = new THREE.MeshToonMaterial({ color: arena.obstacle });
  const ball = new THREE.Mesh(G.sphere, ballMat);
  ball.scale.setScalar(r);
  spinGroup.add(ball);
  // white rings + patches for that inflatable look
  const white = toonMat('#fffaf0');
  mesh(spinGroup, new THREE.TorusGeometry(r * 0.99, r * 0.085, 7, 22), white, [0, 0, 0], [1, 1, 1], [Math.PI / 2, 0, 0]);
  mesh(spinGroup, new THREE.TorusGeometry(r * 0.7, r * 0.07, 7, 20), white, [0, 0, 0], [1, 1, 1], [0, 0, Math.PI / 2]);
  for (let i = 0; i < 5; i++) {
    const a = i / 5 * Math.PI * 2;
    const patch = mesh(spinGroup, G.sphere, white, [Math.cos(a) * r * 0.76, Math.sin(a * 1.3) * r * 0.4, Math.sin(a) * r * 0.76], [r * 0.2, r * 0.2, r * 0.06]);
    patch.lookAt(0, 0, 0);
  }
  // cheerful googly eyes on a non-rolling child so the ball can see its victims
  const face = new THREE.Group();
  face.position.set(0, r * 0.35, -r * 0.82);
  group.add(face);
  const eyeW = toonMat('#ffffff');
  const pupil = toonMat('#1a1a1a');
  mesh(face, G.sphere, eyeW, [-r * 0.27, 0, 0], [r * 0.22, r * 0.25, r * 0.12]);
  mesh(face, G.sphere, eyeW, [r * 0.27, 0, 0], [r * 0.22, r * 0.25, r * 0.12]);
  mesh(face, G.sphere, pupil, [-r * 0.27, 0, -r * 0.1], [r * 0.09, r * 0.11, r * 0.06]);
  mesh(face, G.sphere, pupil, [r * 0.27, 0, -r * 0.1], [r * 0.09, r * 0.11, r * 0.06]);

  const spd = opt.speed || 4.2;
  const span = opt.span || 24;
  const phase = opt.phase || 0;

  return {
    type: 'ball', group, power: 8, yTop: opt.top + r * 2,
    update(dt, t) {
      const prog = ((t * spd / span + phase) % 1);
      const z = opt.zFar + prog * span;
      group.position.z = z;
      const bounce = Math.abs(Math.sin(prog * Math.PI * (opt.hops || 2) + phase * 3));
      group.position.y = opt.top + bounce * (opt.bounceHeight || 0.9);
      spinGroup.rotation.x -= dt * spd / r;
      if (face) face.position.y = r * 0.35 + bounce * 0.1;
    },
    hit(pos, radius, height) {
      const center = new THREE.Vector3(opt.x, group.position.y + r, group.position.z);
      const dx = pos.x - center.x, dz = pos.z - center.z;
      const dist = Math.hypot(dx, dz);
      if (dist > r + radius) return null;
      const feet = pos.y, head = pos.y + height;
      if (head < center.y - r || feet > center.y + r) return null;
      let nx = dx / (dist || 1), nz = dz / (dist || 1);
      nz = Math.max(nz, 0.35); // always shove backwards a bit
      return { nx, nz, power: 8.5, up: 2.5, label: 'BONKED BY A BIG RED BALL' };
    }
  };
}

// ---------------------------------------------------------------------------
// ROTATING SWEEPER
// ---------------------------------------------------------------------------
function sweeper(opt, arena) {
  const group = new THREE.Group();
  group.position.set(opt.x || 0, opt.top, opt.z);
  const reach = opt.reach || 7.6;
  const speed = (opt.speed || 1.5) * (opt.dir || 1);

  const hub = mesh(group, G.cyl, toonMat(arena.platformTrim), [0, 0.75, 0], [0.75, 1.5, 0.75]);
  mesh(group, G.cyl, toonMat('#30363f'), [0, 1.52, 0], [0.9, 0.12, 0.9]);
  glow(group, arena.accent, [0, 1.72, 0], 0.22);

  const arm = new THREE.Group();
  arm.position.y = 0.78;
  group.add(arm);
  const bar = mesh(arm, G.cylAxisX, hazardMat(arena), [0, 0, 0], [reach, 0.62, 0.62]);
  bar.rotation.z = Math.PI / 2;
  mesh(arm, G.cylAxisX, toonMat('#30363f'), [0, 0, 0], [reach, 0.3, 0.3]);
  // end caps
  [-1, 1].forEach(s => {
    mesh(arm, G.sphere, toonMat(arena.accent), [s * reach, 0, 0], [0.55, 0.55, 0.55]);
    glow(arm, arena.accent, [s * reach, 0.35, 0], 0.14);
  });
  // paddles for visibility
  for (let i = -2; i <= 2; i++) {
    if (i === 0) continue;
    mesh(arm, G.box, toonMat(arena.platformTrim), [i * reach * 0.32, 0.35, 0], [1.1, 0.12, 0.6]);
  }

  // support base
  mesh(group, G.cyl, toonMat(arena.platformSide), [0, -0.4, 0], [1.2, 0.8, 1.2]);

  return {
    type: 'sweeper', group, power: 11,
    update(dt, t) {
      const angle = t * speed + (opt.phase || 0);
      arm.rotation.y = angle;
      this.angle = angle;
    },
    hit(pos, radius, height) {
      if (pos.y > opt.top + 1.15) return null; // jumped clean over
      if (pos.y + height < opt.top + 0.15) return null;
      const ang = this.angle || 0;
      const dx = pos.x - group.position.x, dz = pos.z - group.position.z;
      const cos = Math.cos(ang), sin = Math.sin(ang);
      const lx = dx * cos - dz * sin;
      const lz = dx * sin + dz * cos;
      if (Math.abs(lx) > reach + radius || Math.abs(lz) > 0.55 + radius) return null;
      if (Math.hypot(lx, lz) < 0.8) return null;
      const sgn = Math.sign(speed);
      const tx = -Math.sin(ang) * sgn, tz = -Math.cos(ang) * sgn;
      return { nx: tx, nz: tz + 0.35, power: 11, up: 3.6, label: 'SWEPT OFF YOUR FEET' };
    }
  };
}

// ---------------------------------------------------------------------------
// SWINGING HAMMER
// ---------------------------------------------------------------------------
function hammer(opt, arena) {
  const group = new THREE.Group();
  group.position.set(opt.x || 0, opt.top, opt.z);
  const h = opt.pivotH || 5.4;
  const len = opt.arm || 4.0;
  const amp = opt.amp || 1.2;
  const speed = opt.speed || 1.35;
  const axis = opt.axis || 'x';
  const phase = opt.phase || 0;

  // gantry frame
  const frameMat = toonMat(arena.platformSide);
  const postMat = toonMat(arena.platformTrim);
  mesh(group, G.box, frameMat, [-reachX(opt), h * 0.72, 0], [0.6, h * 2, 0.6]);
  mesh(group, G.box, frameMat, [reachX(opt), h * 0.72, 0], [0.6, h * 2, 0.6]);
  mesh(group, G.box, postMat, [0, h, 0], [reachX(opt) * 2 + 0.6, 0.7, 0.7]);
  glow(group, arena.accent, [0, h + 0.5, 0], 0.2);

  const swing = new THREE.Group();
  swing.position.set(0, h, 0);
  group.add(swing);
  // chain
  mesh(swing, G.cyl, toonMat('#4a4f59'), [0, -len / 2, 0], [0.16, len, 0.16]);
  for (let i = 1; i < 5; i++) {
    mesh(swing, G.torus, toonMat('#8e98a3'), [0, -len * i / 5, 0], [0.25, 0.25, 0.25], [Math.PI / 2, 0, 0]);
  }
  // glove
  const glove = new THREE.Group();
  glove.position.y = -len;
  swing.add(glove);
  mesh(glove, G.sphere, toonMat(arena.obstacle), [0, 0, 0], [1.15, 1.1, 1.15]);
  mesh(glove, G.cyl, toonMat('#f6f6fa'), [0, -0.75, 0], [0.72, 0.4, 0.72]);
  mesh(glove, G.sphere, toonMat(arena.obstacle), [0.55, 0.5, -0.55], [0.4, 0.4, 0.4]);
  glow(glove, arena.accent, [0, 1.2, 0], 0.13);

  const headWorld = new THREE.Vector3();

  return {
    type: 'hammer', group, power: 13,
    update(dt, t) {
      const a = Math.sin(t * speed + phase) * amp;
      if (axis === 'x') swing.rotation.z = a;
      else swing.rotation.x = a;
      glove.getWorldPosition(headWorld);
    },
    hit(pos, radius, height) {
      const gh = headWorld;
      const dx = pos.x - gh.x, dy = pos.y + height * 0.5 - gh.y, dz = pos.z - gh.z;
      const rr = 1.15 + radius;
      if (dx * dx + dz * dz > rr * rr) return null;
      if (Math.abs(dy) > 1.15 + height * 0.5) return null;
      const len2 = Math.hypot(dx, dz) || 1;
      return { nx: dx / len2, nz: dz / len2 + 0.4, power: 13, up: 4.2, label: 'HAMMERED!' };
    }
  };
}
function reachX(opt) { return opt.frame || 5.4; }

// ---------------------------------------------------------------------------
// PUNCHING GLOVE
// ---------------------------------------------------------------------------
function punch(opt, arena) {
  const group = new THREE.Group();
  group.position.set(opt.x || 0, opt.top, opt.z);
  const side = opt.side || 1;
  const baseX = side * (opt.mountX || 6.4);
  const period = opt.period || 2.6;
  const extendMax = opt.extend || 4.2;
  const phase = opt.phase || 0;

  const mount = new THREE.Group();
  mount.position.set(baseX, 0.95, 0);
  group.add(mount);
  mesh(mount, G.box, toonMat(arena.platformSide), [0, -0.45, 0], [1.5, 1.6, 1.6]);
  const warn = glow(mount, arena.accent, [0, 0.6, 0.9], 0.2);
  mesh(mount, G.cylAxisX, toonMat('#afb9c4'), [side * -0.9, 0, 0], [1.8, 0.34, 0.34]);
  const glove = new THREE.Group();
  glove.position.set(0, 0, 0);
  mount.add(glove);
  mesh(glove, G.sphere, toonMat(arena.obstacle), [0, 0, 0], [0.95, 0.82, 0.82]);
  mesh(glove, G.cylAxisX, toonMat('#f6f6fa'), [side * 0.95, 0, 0], [0.55, 0.72, 0.72]);
  mesh(glove, G.sphere, toonMat(arena.obstacle), [0, 0.5, 0.35], [0.32, 0.32, 0.32]);

  let curExt = 0;
  return {
    type: 'punch', group, power: 9.5,
    update(dt, t) {
      const p = ((t / period + phase) % 1);
      let ext;
      if (p < 0.55) {
        const q = p / 0.55;
        ext = q < 0.35 ? -0.55 * (q / 0.35) : (q - 0.35) / 0.65 * (extendMax + 0.55) - 0.55;
      } else {
        const q = (p - 0.55) / 0.45;
        ext = extendMax * (1 - q * q);
      }
      curExt = ext;
      glove.position.x = side * -ext;
      warn.scale.setScalar(p > 0.8 ? 0.2 + Math.sin(t * 22) * 0.07 + 0.18 : 0.14);
    },
    hit(pos, radius, height) {
      const gx = group.position.x + baseX + side * -curExt;
      const gy = opt.top + 0.95;
      const dx = pos.x - gx, dz = pos.z - group.position.z;
      const rr = 0.95 + radius;
      if (dx * dx + dz * dz > rr * rr) return null;
      if (pos.y > gy + 0.95 || pos.y + height < gy - 0.95) return null;
      return { nx: -side * 0.9, nz: 0.55, power: 9.5, up: 3.2, label: 'SURPRISE PUNCH!' };
    }
  };
}

// ---------------------------------------------------------------------------
// MOVING WALL
// ---------------------------------------------------------------------------
function movingWall(opt, arena) {
  const group = new THREE.Group();
  group.position.set(0, opt.top, opt.z);
  const w = opt.w || 3.4;
  const h = 2.4;
  const move = new THREE.Group();
  group.add(move);
  mesh(move, G.box, hazardMat(arena), [0, h / 2, 0], [w, h, 0.5]);
  mesh(move, G.box, toonMat(arena.platformSide), [0, h + 0.08, 0], [w + 0.2, 0.16, 0.7]);
  [-1, 1].forEach(s => {
    mesh(move, G.cyl, toonMat(arena.platformSide), [s * w * 0.42, h / 2, 0.32], [0.22, h, 0.22]);
    glow(move, arena.accent, [s * w * 0.42, h + 0.22, 0.3], 0.13);
  });
  // track
  mesh(group, G.box, toonMat('#30363f'), [0, 0.04, 0], [opt.track || 12, 0.08, 0.75]);
  const amp = opt.amp || 4;
  const speed = opt.speed || 1.1;
  const phase = opt.phase || 0;
  let x = 0;

  return {
    type: 'wall', group, power: 8.5,
    update(dt, t) {
      x = Math.sin(t * speed + phase) * amp + (opt.x || 0);
      move.position.x = x;
      move.rotation.z = Math.sin(t * speed + phase) * 0.02;
    },
    hit(pos, radius, height) {
      if (pos.y > opt.top + h) return null;
      if (pos.y + height < opt.top) return null;
      const dx = pos.x - group.position.x - x;
      if (Math.abs(dx) > w / 2 + radius) return null;
      if (Math.abs(pos.z - group.position.z) > 0.3 + radius) return null;
      const vx = Math.cos(tNow * speed + phase) * amp * speed;
      return { nx: Math.sign(vx || 1), nz: 0.5, power: 8.5, up: 2.2, label: 'CLOTHESLINED BY A WALL' };
    }
  };
}
let tNow = 0;

// ---------------------------------------------------------------------------
// ROLLING CYLINDER
// ---------------------------------------------------------------------------
function roller(opt, arena) {
  const group = new THREE.Group();
  group.position.set(opt.x || 0, opt.top + (opt.radius || 0.55), opt.z || 0);
  const r = opt.radius || 0.55;
  const len = opt.len || 5.2;
  const bar = new THREE.Mesh(G.cylAxisX, new THREE.MeshToonMaterial({ map: stripeTexture('#f6f6fa', arena.obstacle, 3) }));
  bar.scale.set(r, r, r);
  bar.scale.x = r;
  // using cylinder axis X geometry: scale radius in Y/Z and length in X
  bar.scale.set(len, r, r);
  group.add(bar);
  [-1, 1].forEach(s => mesh(group, G.cylAxisX, toonMat(arena.platformSide), [s * len / 2, 0, 0], [0.12, r * 1.02, r * 1.02]));
  const span = opt.span || 26;
  const speed = opt.speed || 5;

  return {
    type: 'roller', group, power: 7,
    update(dt, t) {
      const prog = ((t * speed / span + (opt.phase || 0)) % 1);
      group.position.z = opt.zFar + prog * span;
      group.rotation.x = -prog * span / r;
    },
    hit(pos, radius, height) {
      const dx = pos.x - group.position.x, dz = pos.z - group.position.z;
      const rr = r + radius;
      if (dx * dx + dz * dz > rr * rr) return null;
      if (pos.y > group.position.y + r * 0.85) return null;
      if (pos.y + height < group.position.y - r) return null;
      const nz = dz / (Math.hypot(dx, dz) || 1);
      return { nx: dx / (Math.hypot(dx, dz) || 1) * 0.5, nz: 0.5 + nz, power: 7, up: 2.4, label: 'FLATTENED BY A ROLLER' };
    }
  };
}

// ---------------------------------------------------------------------------
// LAUNCH PAD (trigger, not knockback)
// ---------------------------------------------------------------------------
function launchPad(opt, arena) {
  const group = new THREE.Group();
  group.position.set(opt.x || 0, opt.top, opt.z);
  const mat = toonMat(arena.accent2, { emissive: arena.accent2, emissiveIntensity: 0.35 });
  mesh(group, G.cyl, mat, [0, 0.09, 0], [1.9, 0.16, 1.9]);
  mesh(group, new THREE.CylinderGeometry(1.5, 1.7, 0.12, 16), toonMat('#f6f6fa'), [0, 0.19, 0], [1, 1, 1]);
  for (let i = 0; i < 3; i++) {
    const a = mesh(group, new THREE.ConeGeometry(0.45, 0.9, 4), toonMat(arena.accent), [0, 0.5, -1.3 + i * 0.75], [1, 1, 1], [Math.PI / 2, 0, 0]);
    a.rotation.x = 0;
  }
  const spring = mesh(group, G.box, toonMat('#30363f'), [0, 0.22, 0], [2.8, 0.1, 2.8]);
  const arrowMat = toonMat(arena.accent, { emissive: arena.accent, emissiveIntensity: 0.6 });
  const arrows = [];
  for (let i = 0; i < 2; i++) {
    const a = mesh(group, new THREE.ConeGeometry(0.55, 1.1, 3), arrowMat, [0, 0.35, 1.2 + i * 0.9], [1, 1, 1], [Math.PI / 2, 0, 0]);
    arrows.push(a);
  }
  let cooldown = 0;
  return {
    type: 'launch', group, power: 0, box: { w: 3.2, d: 3.2 },
    update(dt, t) {
      cooldown = Math.max(0, cooldown - dt);
      spring.scale.y = 1 + Math.sin(t * 5) * 0.4;
      arrows.forEach((a, i) => {
        a.position.z = 1.1 + ((t * 2.2 + i * 0.9) % 1.8);
        a.material.opacity = 1;
      });
    },
    tryLaunch(pos, feetY) {
      if (cooldown > 0) return false;
      if (Math.abs(pos.x - (opt.x || 0)) > 1.8 || Math.abs(pos.z - opt.z) > 1.8) return false;
      if (Math.abs(feetY - opt.top) > 0.5) return false;
      cooldown = 1;
      return { power: opt.power || 15, forward: opt.forward || 7 };
    },
    hit() { return null; }
  };
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------
const BUILDERS = { ball: bigBall, sweeper, hammer, punch, wall: movingWall, roller, launch: launchPad };

export function createObstacle(type, opt, arena) {
  const build = BUILDERS[type];
  if (!build) throw new Error('Unknown obstacle ' + type);
  return build(opt, arena);
}

export function tickWallTime(t) { tNow = t; }

// checkpoint gate visual
export function createCheckpointGate(arena, z, index) {
  const group = new THREE.Group();
  group.position.set(0, 0.3, z);
  const postMat = toonMat(arena.platformSide);
  const glowMat = toonMat('#6bff9d', { emissive: '#38ff7d', emissiveIntensity: 1 });
  [-1, 1].forEach(s => {
    mesh(group, G.box, postMat, [s * 7, 1.8, 0], [0.5, 3.6, 0.5]);
    mesh(group, G.sphere, glowMat, [s * 7, 3.65, 0], [0.35, 0.35, 0.35]);
  });
  const banner = mesh(group, G.plane || new THREE.PlaneGeometry(1, 1), toonMat(arena.accent), [0, 3.3, 0], [13.4, 0.8, 1]);
  banner.rotation.y = 0;
  return group;
}

import * as THREE from 'three';
import { toonMat } from './characterRig.js';
import { createObstacle, createCheckpointGate, WATER_Y } from './obstacles.js';

function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

function hashSeed(round, arena, extra) {
  let h = 2166136261;
  for (const ch of round + arena + extra) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

const G = {
  box: new THREE.BoxGeometry(1, 1, 1),
  sphere: new THREE.SphereGeometry(1, 12, 9),
  cyl: new THREE.CylinderGeometry(1, 1, 1, 14),
  torus: new THREE.TorusGeometry(1, 0.1, 6, 18)
};

function m(parent, geom, mat, pos, scale, rot) {
  const mesh = new THREE.Mesh(geom, mat);
  if (pos) mesh.position.set(...pos);
  if (scale) mesh.scale.set(...scale);
  if (rot) mesh.rotation.set(...rot);
  parent.add(mesh);
  return mesh;
}

// Top colour with a subtle painted stripe texture so large surfaces don't read flat.
const topTextures = new Map();
function platformTexture(base, trim, kind) {
  const key = base + trim + kind;
  if (topTextures.has(key)) return topTextures.get(key);
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, 128, 128);
  ctx.globalAlpha = 0.08;
  ctx.fillStyle = '#000';
  for (let i = -128; i < 256; i += 24) {
    ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + 10, 0); ctx.lineTo(i - 118, 128); ctx.lineTo(i - 128, 128); ctx.fill();
  }
  ctx.globalAlpha = 1;
  if (kind === 'slippery') {
    ctx.strokeStyle = 'rgba(255,255,255,.45)';
    ctx.lineWidth = 3;
    for (let i = 0; i < 6; i++) {
      ctx.beginPath();
      ctx.arc(20 + (i * 37) % 100, 24 + (i * 53) % 90, 8 + (i % 3) * 4, 0.2, 2.9);
      ctx.stroke();
    }
  }
  if (kind === 'start') {
    ctx.fillStyle = trim;
    ctx.globalAlpha = 0.8;
    ctx.beginPath();
    ctx.moveTo(64, 22); ctx.lineTo(84, 62); ctx.lineTo(72, 62); ctx.lineTo(72, 104);
    ctx.lineTo(56, 104); ctx.lineTo(56, 62); ctx.lineTo(44, 62); ctx.closePath(); ctx.fill();
    ctx.globalAlpha = 1;
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  topTextures.set(key, tex);
  return tex;
}

export function buildCourse({ round, arena, difficulty = 1, seedExtra = '', endlessLevel = 0 }) {
  const group = new THREE.Group();
  const platforms = [];
  const obstacles = [];
  const pads = [];
  const checkpoints = [];
  const rand = rng(hashSeed(round, arena.id, seedExtra + endlessLevel));
  const theme = arena;

  let cursor = -2; // front edge of the last platform
  let platformId = 0;

  const topMat = (color, trim, kind) => {
    const tex = platformTexture(color, trim, kind);
    const t = tex.clone();
    t.needsUpdate = true;
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(1.5, 1.5);
    return new THREE.MeshToonMaterial({ map: t });
  };

  function addPlatform(opt) {
    const {
      x = 0, zBack, depth, w = 13, top = 0, kind = 'flat',
      color = theme.platform, sideColor = theme.platformSide, trim = theme.platformTrim,
      slippery = false, hole = false
    } = opt;
    const zFront = zBack - depth;
    const z = (zBack + zFront) / 2;
    const p = {
      id: platformId++, kind, x, z, w, d: depth, top, zBack, zFront,
      slippery, active: true, slopeX: opt.slopeX || 0, slopeZ: opt.slopeZ || 0,
      conveyor: opt.conveyor || null, spinRate: opt.spinRate || 0, mesh: null,
      collapse: opt.collapse || null, beam: kind === 'beam',
      topAt(px, pz) { return top + this.slopeX * (px - this.x) + this.slopeZ * (pz - this.z); },
      contains(px, pz) {
        if (kind === 'disc') return Math.hypot(px - x, pz - z) <= w / 2 + (opt.edge ?? 0.06);
        return Math.abs(px - x) <= w / 2 + (opt.edge ?? 0.06) && px > -900 &&
          pz <= zBack + (opt.edge ?? 0.06) && pz >= zFront - (opt.edge ?? 0.06);
      }
    };
    platforms.push(p);
    if (hole) return p;
    const pg = new THREE.Group();
    group.add(pg);
    p.mesh = pg;

    if (kind === 'disc') {
      const disc = new THREE.Mesh(new THREE.CylinderGeometry(w / 2, w / 2 - 0.35, 1.2, 26), topMat(color, trim, 'disc'));
      disc.position.set(x, top - 0.6, z);
      pg.add(disc);
      // rotating top plate marks
      const spin = new THREE.Group();
      spin.position.set(x, top + 0.01, z);
      pg.add(spin);
      const stripeMat = toonMat(theme.platformTrim);
      for (let i = 0; i < 4; i++) {
        m(spin, G.box, stripeMat, [0, 0.02, 0], [w * 0.88, 0.04, 0.28]).rotation.y = (i / 4) * Math.PI;
      }
      const rim = new THREE.Mesh(new THREE.TorusGeometry(w / 2 - 0.1, 0.18, 6, 28), toonMat(trim));
      rim.rotation.x = Math.PI / 2; rim.position.set(x, top - 0.05, z);
      pg.add(rim);
      m(pg, G.cyl, toonMat('#30363f'), [x, top + 0.5, z], [0.8, 1.4, 0.8]);
      m(pg, G.cyl, toonMat(theme.accent), [x, top + 1.3, z], [1.1, 0.2, 1.1]);
      p.spinMesh = spin;
      return p;
    }

    const depthT = kind === 'beam' ? 1.3 : 2.6;
    const slab = new THREE.Mesh(new THREE.BoxGeometry(w, depthT, depth), topMat(color, trim, kind));
    slab.position.set(x, top - depthT / 2, z);
    pg.add(slab);
    // skirt
    const skirtH = kind === 'beam' ? 0.7 : 1.35;
    const skirt = new THREE.Mesh(
      new THREE.BoxGeometry(w - 0.25, skirtH, depth - 0.25),
      toonMat(sideColor)
    );
    skirt.position.set(x, top - depthT - skirtH / 2 + 0.05, z);
    pg.add(skirt);
    // edge trims
    const edgeMat = toonMat(trim);
    const edgeH = 0.13;
    const longZ = kind === 'beam';
    if (!longZ) {
      m(pg, G.box, edgeMat, [x - w / 2 + 0.16, top + 0.06, z], [0.34, edgeH, depth]);
      m(pg, G.box, edgeMat, [x + w / 2 - 0.16, top + 0.06, z], [0.34, edgeH, depth]);
    }
    m(pg, G.box, edgeMat, [x, top + 0.06, zBack - 0.18], [w, edgeH, 0.36]);
    m(pg, G.box, edgeMat, [x, top + 0.06, zFront + 0.18], [w, edgeH, 0.36]);
    // corner floaters
    const cornerMat = toonMat(theme.accent);
    if (kind !== 'beam') {
      [[-1, -1], [1, -1], [-1, 1], [1, 1]].forEach(([sx, sz]) => {
        m(pg, G.sphere, cornerMat, [x + sx * (w / 2 - 0.5), top - 0.1, z + sz * (depth / 2 - 0.5)], [0.55, 0.45, 0.55]);
      });
    }
    if (slippery) {
      const ice = new THREE.Mesh(new THREE.BoxGeometry(w - 0.5, 0.06, depth - 0.3), new THREE.MeshToonMaterial({
        color: '#bdefff', transparent: true, opacity: 0.35
      }));
      ice.position.set(x, top + 0.045, z);
      pg.add(ice);
    }
    // support pylons (only for wide platforms)
    if (kind === 'flat' && depth > 8) {
      [[-1, -1], [1, -1], [-1, 1], [1, 1]].forEach(([sx, sz]) => {
        m(pg, G.cyl, toonMat(sideColor), [x + sx * (w / 2 - 1), top - 2.1, z + sz * (depth / 2 - 1)], [0.35, 1.7, 0.35]);
      });
    }
    return p;
  }

  function nextSection(depth, opt = {}) {
    const gap = opt.gap ?? 2.4;
    const zBack = cursor - gap;
    const p = addPlatform({ ...opt, zBack, depth });
    cursor = zBack - depth;
    return p;
  }

  function addCheckpoint(p, label, index) {
    const z = p.z + p.d / 2 - 2.2;
    const gate = createCheckpointGate(theme, z, index);
    group.add(gate);
    checkpoints.push({
      index, label, z, platform: p,
      respawn: { x: p.x, z: z - 0.8, top: p.topAt(p.x, z) }
    });
  }

  function addObs(type, opt) {
    const o = createObstacle(type, opt, theme);
    group.add(o.group);
    obstacles.push(o);
    if (type === 'launch') pads.push(o);
    return o;
  }

  function decorateSection(p, opts = {}) {
    // hazard rail lights along the sides
    const lightMat = toonMat(theme.accent, { emissive: theme.accent, emissiveIntensity: 0.8 });
    const n = Math.max(1, Math.floor(p.d / 7));
    for (let i = 0; i < n; i++) {
      const zz = p.zBack - (i + 0.5) * (p.d / n);
      [-1, 1].forEach(s => {
        if (p.kind === 'beam') return;
        m(group, G.sphere, lightMat, [p.x + s * (p.w / 2 - 0.4), p.top + 0.6, zz], [0.11, 0.11, 0.11]);
      });
    }
    if (opts.arch) {
      const archMat = toonMat(theme.accent);
      const arch = new THREE.Mesh(new THREE.TorusGeometry(p.w / 2 + 1.2, 0.35, 7, 24, Math.PI), archMat);
      arch.position.set(p.x, p.top + 2.4, p.z + p.d / 2 - 1);
      group.add(arch);
      const sign = m(group, new THREE.PlaneGeometry(6, 1.4), toonMat(theme.accent2), [p.x, p.top + 5.4, p.z + p.d / 2 - 1], [1, 1, 1]);
      sign.rotation.y = 0;
    }
  }

  // =========================================================================
  // START
  // =========================================================================
  const start = addPlatform({ zBack: 14, depth: 16, w: 16, top: 0, kind: 'start' });
  cursor = -2;
  start.isStart = true;
  // start gantry
  {
    const g = new THREE.Group();
    group.add(g);
    const postMat = toonMat(theme.platformSide);
    [-1, 1].forEach(s => {
      m(g, G.box, postMat, [s * 7.4, 2.4, 9], [0.7, 4.8, 0.7]);
      m(g, G.sphere, toonMat(theme.accent, { emissive: theme.accent, emissiveIntensity: 0.6 }), [s * 7.4, 4.9, 9], [0.5, 0.5, 0.5]);
    });
    m(g, G.box, toonMat(theme.accent), [0, 5.3, 9], [15.5, 0.9, 0.6]);
    const banner = m(g, G.box, toonMat('#101b2b'), [0, 3.8, 8.9], [10, 1.8, 0.25]);
    const startLights = new THREE.Group();
    for (let i = 0; i < 3; i++) {
      const light = m(startLights, G.sphere, toonMat('#ff4d5e', { emissive: '#ff4d5e', emissiveIntensity: 1.2 }), [(i - 1) * 1.5, 4.2, 8.6], [0.4, 0.4, 0.4]);
      light.userData.startLight = i;
    }
    g.add(startLights);
    start.lights = startLights;
  }
  checkpoints.push({
    index: 0, label: 'START', z: 12, platform: start,
    respawn: { x: 0, z: 8, top: 0 }
  });

  // =========================================================================
  // SECTION BUILDERS
  // =========================================================================
  const builders = {
    balls(p) {
      const laneXs = p.w > 13 ? [-4.2, 0, 4.2] : [-3.2, 3.2];
      const count = difficulty > 1.12 ? 3 : 2;
      for (let i = 0; i < count; i++) {
        addObs('ball', {
          x: laneXs[i % laneXs.length] + (rand() - 0.5) * 0.8,
          top: p.top, zFar: p.zFront + 1, span: p.d + 3,
          speed: 4.0 + rand() * 1.2 + difficulty * 0.3,
          phase: rand(), radius: 1.75,
          bounceHeight: 1.0
        });
      }
      decorateSection(p);
    },
    sweepers(p, n = 1) {
      for (let i = 0; i < n; i++) {
        const zz = p.zBack - p.d * (i + 0.5) / n;
        addObs('sweeper', {
          x: 0, z: zz, top: p.top, reach: Math.min(6.6, p.w / 2 - 0.2),
          speed: (1.35 + rand() * 0.35) * (difficulty > 1.15 ? 1.2 : 1),
          dir: i % 2 ? -1 : 1, phase: rand() * 2
        });
      }
      decorateSection(p);
    },
    hammers(p, n = 2) {
      for (let i = 0; i < n; i++) {
        const zz = p.zBack - p.d * (i + 0.5) / n;
        addObs('hammer', {
          x: p.x, z: zz, top: p.top, pivotH: 5.2, arm: p.kind === 'beam' ? 3.6 : 3.9,
          amp: 1.15, speed: 1.25 + rand() * 0.3, phase: rand() * 3
        });
      }
      decorateSection(p);
    },
    punches(p, n = 2) {
      for (let i = 0; i < n; i++) {
        const zz = p.zBack - p.d * (i + 0.5) / n;
        const side = i % 2 ? 1 : -1;
        addObs('punch', {
          x: p.x, z: zz, top: p.top, side, mountX: p.w / 2 + 0.3,
          period: 2.3 + rand() * 0.4, extend: p.w * 0.36, phase: rand()
        });
      }
      decorateSection(p);
    },
    walls(p, n = 2) {
      for (let i = 0; i < n; i++) {
        const zz = p.zBack - p.d * (i + 0.5) / n;
        addObs('wall', {
          x: p.x, z: zz, top: p.top, w: 3.5, amp: Math.max(2.6, p.w / 2 - 2.6),
          speed: 0.95 + rand() * 0.3, phase: rand() * 2, track: p.w - 1
        });
      }
      decorateSection(p);
    },
    rollers(p, n = 2) {
      for (let i = 0; i < n; i++) {
        addObs('roller', {
          x: (i - (n - 1) / 2) * 3.2 + p.x, top: p.top, zFar: p.zFront + 1,
          span: p.d + 3, radius: 0.55, len: 4.6, speed: 4.5 + rand() * 1.5,
          phase: rand()
        });
      }
      decorateSection(p);
    },
    launch(p) {
      addObs('launch', { x: p.x, z: p.z + 1, top: p.top, power: 16, forward: 6 });
      decorateSection(p);
    }
  };

  // collapsing section uses individual tiles
  function addCollapseSection(depth = 22, width = 13) {
    const gap = 2.2;
    const zBack = cursor - gap;
    const zFront = zBack - depth;
    const cols = 4, rows = 5;
    const tw = width / cols - 0.18, td = depth / rows - 0.18;
    const pg = new THREE.Group();
    group.add(pg);
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const tx = -width / 2 + tw / 2 + c * (tw + 0.18);
        const tz = zBack - td / 2 - r * (td + 0.18);
        const tile = addPlatform({
          x: tx, zBack: tz + td / 2, depth: td, w: tw, top: 0,
          kind: 'tile', color: (r + c) % 2 ? theme.platform : theme.platformSide,
          edge: 0.01
        });
        // replace visual with a chunkier tile
        if (tile.mesh) {
          tile.mesh.position.y = 0;
          tile.tileMesh = tile.mesh;
        }
        tile.collapse = { period: 3.4, offset: r * 0.42 + c * 0.15 + rand() * 0.12, off: 0.95, active: true };
        tile.active = true;
        tile.baseTop = 0;
      }
    }
    cursor = zFront;
    // safety rails on edges
    return { zBack, zFront };
  }

  function addDiscSection(count = 2) {
    const zBack = cursor - 3;
    let zz = zBack;
    for (let i = 0; i < count; i++) {
      const p = addPlatform({
        x: (i - (count - 1) / 2) * 5.4 + (rand() - 0.5) * 1.2,
        zBack: zz, depth: 8.5, w: 8.6, top: 0, kind: 'disc',
        spinRate: (i % 2 ? -1 : 1) * (1.0 + rand() * 0.5)
      });
      p.d = 8.5;
      zz = zz - 8.5 - 3.4;
    }
    cursor = zz + 3.4;
    return zz;
  }

  // =========================================================================
  // ROUND LAYOUTS
  // =========================================================================
  const isEndless = endlessLevel > 0;
  const diff = difficulty * (1 + endlessLevel * 0.06);

  if (round === 'qualifier') {
    addCheckpoint(start, 'START', 0);
    const p1 = nextSection(24, { w: 14 });
    builders.balls(p1);
    const p2 = nextSection(20, { w: 14, slippery: true, conveyor: { x: (rand() > 0.5 ? 1 : -1) * 1.5 } });
    addObs('rollor', {}); // harmless typo guard removed below
    builders.rollers(p2, 2);
    addCheckpoint(p2, 'CHECKPOINT 1', 1);
    const p3 = nextSection(18, { w: 3.6, kind: 'beam', color: theme.platformSide });
    builders.hammers(p3, 1);
    const p4 = nextSection(20, { w: 14 });
    builders.walls(p4, 2);
    const p5 = nextSection(10, { w: 12 });
    builders.launch(p5);
    addCheckpoint(p5, 'CHECKPOINT 2', 2);

  } else if (round === 'sweeper') {
    addCheckpoint(start, 'START', 0);
    const p1 = nextSection(24, { w: 15 });
    builders.sweepers(p1, 2);
    const p2 = nextSection(15, { w: 14 });
    builders.punches(p2, 1);
    addCheckpoint(p2, 'CHECKPOINT 1', 1);
    const p3 = addPlatform({ zBack: cursor - 4, depth: 7, w: 6.5, x: -2.5 });
    cursor = p3.zFront;
    const p4 = addPlatform({ zBack: cursor - 4.5, depth: 7, w: 6.5, x: 2.8 });
    cursor = p4.zFront;
    const p5 = nextSection(22, { w: 15 });
    builders.sweepers(p5, 2);
    addCheckpoint(p5, 'CHECKPOINT 2', 2);
    const p6 = nextSection(18, { w: 3.8, kind: 'beam', color: theme.platformSide });
    builders.hammers(p6, 1);
    const p7 = nextSection(16, { w: 14 });
    builders.walls(p7, 2);
    const p8 = nextSection(9, { w: 12 });
    builders.launch(p8);

  } else if (round === 'dizzy') {
    addCheckpoint(start, 'START', 0);
    addDiscSection(2);
    const p1 = nextSection(24, { w: 15 });
    builders.sweepers(p1, 1);
    builders.hammers(p1, 1);
    addCheckpoint(p1, 'CHECKPOINT 1', 1);
    const p2 = nextSection(22, { w: 13, slippery: true, conveyor: { x: -1.9 } });
    builders.rollers(p2, 2);
    addCollapseSection(22, 13);
    addCheckpoint({ x: 0, z: cursor + 2, d: 1, w: 13, zBack: cursor + 4, zFront: cursor, top: 0, topAt: () => 0, contains: () => true }, 'CHECKPOINT 2', 2);
    addDiscSection(2);
    const p3 = nextSection(20, { w: 3.8, kind: 'beam', color: theme.platformSide });
    builders.hammers(p3, 2);
    const p4 = nextSection(20, { w: 14 });
    builders.punches(p4, 2);
    const p5 = nextSection(9, { w: 12 });
    builders.launch(p5);

  } else { // WIPEOUT ZONE - everything
    addCheckpoint(start, 'START', 0);
    const p1 = nextSection(22, { w: 14 });
    builders.balls(p1);
    const p2 = nextSection(24, { w: 15 });
    builders.sweepers(p2, 2);
    addCheckpoint(p2, 'CHECKPOINT 1', 1);
    const p3 = nextSection(22, { w: 14, slippery: true, conveyor: { x: (rand() > 0.5 ? -1 : 1) * 2.0 } });
    builders.rollers(p3, 2);
    builders.walls(p3, 1);
    addCollapseSection(22, 13);
    const p4 = nextSection(22, { w: 14 });
    builders.punches(p4, 2);
    addCheckpoint(p4, 'CHECKPOINT 2', 2);
    addDiscSection(3);
    const p5 = nextSection(22, { w: 15 });
    builders.sweepers(p5, 1);
    builders.hammers(p5, 1);
    addCheckpoint(p5, 'CHECKPOINT 3', 3);
    const p6 = nextSection(20, { w: 4.0, kind: 'beam', color: theme.platformSide });
    builders.hammers(p6, 2);
    const p7 = nextSection(20, { w: 14 });
    builders.walls(p7, 2);
    const p8 = nextSection(10, { w: 12 });
    builders.launch(p8);
    addCheckpoint(p8, 'FINAL CHECKPOINT', 4);
  }

  // =========================================================================
  // FINISH PLATFORM + ARCH
  // =========================================================================
  const finish = addPlatform({
    zBack: cursor - 3.2, depth: 20, w: 20, kind: 'start',
    color: theme.platform, trim: theme.accent
  });
  const finishZ = finish.zBack - 1.5;
  finish.isFinish = true;
  {
    const g = new THREE.Group();
    group.add(g);
    const postMat = toonMat(theme.platformSide);
    [-1, 1].forEach(s => {
      m(g, G.box, postMat, [s * 9.4, 3, finish.zBack - 4], [0.9, 6, 0.9]);
      m(g, G.sphere, toonMat(theme.accent, { emissive: theme.accent, emissiveIntensity: 0.7 }), [s * 9.4, 6.2, finish.zBack - 4], [0.55, 0.55, 0.55]);
    });
    m(g, G.box, toonMat(theme.accent), [0, 6.7, finish.zBack - 4], [19.5, 1.2, 0.8]);
    // checkered finish line
    const checker = document.createElement('canvas');
    checker.width = 256; checker.height = 64;
    const cx = checker.getContext('2d');
    for (let yy = 0; yy < 4; yy++) for (let xx = 0; xx < 16; xx++) {
      cx.fillStyle = (xx + yy) % 2 ? '#ffffff' : '#151b26';
      cx.fillRect(xx * 16, yy * 16, 16, 16);
    }
    const tex = new THREE.CanvasTexture(checker);
    tex.colorSpace = THREE.SRGBColorSpace;
    const strip = new THREE.Mesh(new THREE.BoxGeometry(19, 0.31, 2.4), new THREE.MeshToonMaterial({ map: tex }));
    strip.position.set(0, 0.09, finish.zBack - 7.4);
    g.add(strip);
    // podium decor
    const colours = ['#ffd23f', '#c9d6e2', '#d08040'];
    for (let i = 0; i < 3; i++) {
      m(g, G.box, toonMat(colours[i]), [(i - 1) * 4, 0.45 + (1 - Math.abs(i - 1)) * 0.4, finish.zBack - 15], [2.4, 0.9 + (1 - Math.abs(i - 1)) * 0.8, 2.4]);
    }
  }

  const length = 14 - (finish.zFront);
  const parTime = length / 6.2 + (round === 'wipeout' ? 12 : round === 'dizzy' ? 9 : 5) + difficulty * 3;

  const course = {
    round, arena: theme, group, platforms, obstacles, pads, checkpoints, finish, finishZ,
    startZ: 8, startX: 0, top: 0, length, parTime,
    startPlatform: start,
    checkpointsSorted: checkpoints.slice().sort((a, b) => a.index - b.index),

    groundAt(x, z, maxY = 999) {
      let best = null;
      for (let i = 0; i < platforms.length; i++) {
        const p = platforms[i];
        if (!p.active) continue;
        if (!p.contains(x, z)) continue;
        const top = p.topAt(x, z);
        if (top <= maxY + 0.06 && (!best || top > best.top)) best = { platform: p, top };
      }
      return best;
    },

    update(dt, t, player) {
      for (let i = 0; i < obstacles.length; i++) obstacles[i].update(dt, t);
      for (let i = 0; i < platforms.length; i++) {
        const p = platforms[i];
        if (p.kind === 'disc' && p.spinMesh) p.spinMesh.rotation.y = t * p.spinRate;
        if (p.collapse) {
          const c = p.collapse;
          const phase = (t + c.offset) % c.period;
          const wasActive = p.active;
          const offStart = c.period - c.off;
          p.active = phase < offStart;
          if (p.mesh) {
            const targetY = p.active ? 0 : -1.4;
            p.mesh.position.y += (targetY - p.mesh.position.y) * Math.min(1, dt * 12);
            if (p.active && !wasActive) p.mesh.position.y = 0;
            // warning shake
            p.mesh.rotation.z = (!p.active ? 0 : (phase > offStart - 0.55 ? Math.sin(t * 45) * 0.035 : 0));
          }
        }
      }
      // start lights go green after countdown
      if (start.lights) {
        start.lights.children.forEach((l, i) => {
          const on = t > 0.2 + i * 0.7;
          l.material = toonMat(on ? '#6bff9d' : '#ff4d5e', { emissive: on ? '#38ff7d' : '#ff4d5e', emissiveIntensity: 1.1 });
        });
      }
    },

    tryLaunch(pos, feetY) {
      for (let i = 0; i < pads.length; i++) {
        const res = pads[i].tryLaunch(pos, feetY);
        if (res) return res;
      }
      return null;
    },

    hitObstacle(pos, radius, height, invuln) {
      for (let i = 0; i < obstacles.length; i++) {
        const o = obstacles[i];
        if (o.type === 'launch') continue;
        const h = o.hit(pos, radius, height);
        if (h) return h;
      }
      return null;
    },

    // height of the course centreline at z, used by AI rivals
    railGround(z, x = 0) {
      const g = this.groundAt(x, z, 999);
      return g ? g.top : null;
    },

    dispose() {
      group.traverse(o => {
        if (o.geometry && !Object.values(G).includes(o.geometry)) {
          // geometries may be shared; only dispose ones we created here
        }
      });
    }
  };
  return course;
}

