110:       collapse: opt.collapse || null, beam: kind === 'beam',
111:       topAt(px, pz) { return top + this.slopeX * (px - this.x) + this.slopeZ * (pz - this.z); },
112:       contains(px, pz) {
113:         if (kind === 'disc') return Math.hypot(px - x, pz - z) <= w / 2 + (opt.edge ?? 0.06);
114:         return Math.abs(px - x) <= w / 2 + (opt.edge ?? 0.06) && px > -900 &&
115:           pz <= zBack + (opt.edge ?? 0.06) && pz >= zFront - (opt.edge ?? 0.06);
116:       }
117:     };
118:     platforms.push(p);
119:     if (hole) return p;
120:     const pg = new THREE.Group();
121:     group.add(pg);
122:     p.mesh = pg;
123: 
124:     if (kind === 'tile') {
125:       const slab = new THREE.Mesh(new THREE.BoxGeometry(w, 0.7, depth), topMat(color, trim, 'tile'));
126:       slab.position.set(x, top - 0.35, z);
127:       pg.add(slab);
128:       return p;
129:     }
130: 
131:     if (kind === 'disc') {
132:       const disc = new THREE.Mesh(new THREE.CylinderGeometry(w / 2, w / 2 - 0.35, 1.2, 26), topMat(color, trim, 'disc'));
133:       disc.position.set(x, top - 0.6, z);
134:       pg.add(disc);
