356:         const tz = zBack - td / 2 - r * (td + 0.18);
357:         const tile = addPlatform({
358:           x: tx, zBack: tz + td / 2, depth: td, w: tw, top: 0,
359:           kind: 'tile', color: (r + c) % 2 ? theme.platform : theme.platformSide,
360:           edge: 0.01
361:         });
362:         // replace visual with a chunkier tile
363:         if (tile.mesh) {
364:           tile.mesh.position.y = 0;
365:           tile.tileMesh = tile.mesh;
366:         }
367:         tile.collapse = { period: 3.4, offset: r * 0.42 + c * 0.15 + rand() * 0.12, off: 0.95, active: true };
368:         tile.active = true;
