523:   const course = {
524:     round, arena: theme, group, platforms, obstacles, pads, checkpoints, finish, finishZ,
525:     startZ: 8, startX: 0, top: 0, length, parTime,
526:     startPlatform: start,
527:     checkpointsSorted: checkpoints.slice().sort((a, b) => a.index - b.index),
