529:     groundAt(x, z, maxY = 999) {
530:       let best = null;
531:       for (let i = 0; i < platforms.length; i++) {
532:         const p = platforms[i];
533:         if (!p.active) continue;
534:         if (!p.contains(x, z)) continue;
535:         const top = p.topAt(x, z);
536:         if (top <= maxY + 0.06 && (!best || top > best.top)) best = { platform: p, top };
537:       }
538:       return best;
