540: 
541:     update(dt, t, player) {
542:       for (let i = 0; i < obstacles.length; i++) obstacles[i].update(dt, t);
543:       for (let i = 0; i < platforms.length; i++) {
544:         const p = platforms[i];
545:         if (p.kind === 'disc' && p.spinMesh) p.spinMesh.rotation.y = t * p.spinRate;
546:         if (p.collapse) {
547:           const c = p.collapse;
548:           const phase = (t + c.offset) % c.period;
549:           const wasActive = p.active;
550:           const offStart = c.period - c.off;
551:           p.active = phase < offStart;
552:           if (p.mesh) {
553:             const targetY = p.active ? 0 : -1.4;
554:             p.mesh.position.y += (targetY - p.mesh.position.y) * Math.min(1, dt * 12);
555:             if (p.active && !wasActive) p.mesh.position.y = 0;
556:             // warning shake
557:             p.mesh.rotation.z = (!p.active ? 0 : (phase > offStart - 0.55 ? Math.sin(t * 45) * 0.035 : 0));
558:           }
559:         }
560:       }
561:       // start lights go green after countdown
562:       if (start.lights) {
